-- Fixed, bounded review approval. No credential reads and no Pin dispatch.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table reviewed_input as select * from jsonb_to_recordset('[{"queue_id": "d9e22315-f85e-47bd-885f-1c77d779f7ca", "shop": "ChicDecorHK", "listing_id": "1721799800", "source_url": "https://www.etsy.com/listing/1721799800/handcrafted-scallop-shell-necklace-beach", "category": "Seashell Jewelry", "image_url": null, "destination_url": "https://www.etsy.com/listing/1721799800/handcrafted-scallop-shell-necklace-beach", "title": "Handcrafted Scallop Shell Necklace: Beach Style Ceramic Bead Jewelry", "body": "Handcrafted Scallop Shell Necklace: Beach Style Ceramic Bead Jewelry Style: coastal, beach, shell. Materials: shell, ceramic. View details and available options on Etsy.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": null, "new_title": "Scallop Shell Necklace with White Ceramic Beads", "new_body": "A natural scallop shell pendant with gold-toned edging and white ceramic beads. Add a coastal detail to a simple outfit. From ChicDecorHK. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/32003756/r/il/ff1475/6058065789/il_1588xN.6058065789_con2.jpg", "checked_at": "2026-10-13T03:23:58.281Z"}, {"queue_id": "a92c074d-ec89-46c6-ac40-9e74bef11a49", "shop": "PearlsTreasuresArt", "listing_id": "1904477471", "source_url": "https://www.etsy.com/listing/1904477471/seashell-pearl-drop-earrings-gold-hoop", "category": "Seashell Jewelry", "image_url": null, "destination_url": "https://www.etsy.com/listing/1904477471/seashell-pearl-drop-earrings-gold-hoop", "title": "Seashell Pearl Drop Earrings: Gold Hoop Coastal Jewelry", "body": "Seashell Pearl Drop Earrings: Gold Hoop Coastal Jewelry Style: coastal, minimal, shell. Materials: shell, pearl, metal. View details and available options on Etsy.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": null, "new_title": "Seashell Drop Earrings for Coastal Style", "new_body": "Natural seashell drops and gold-toned hoops for coastal outfits. Explore the shell and pearl style options in the listing. From PearlsTreasuresArt. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/46725934/r/il/bdd26b/6846441847/il_1588xN.6846441847_myf4.jpg", "checked_at": "2026-10-13T03:24:36.122Z"}, {"queue_id": "afa2833f-686e-41ed-9280-a8623307ee87", "shop": "PearlsTreasuresArt", "listing_id": "4339516931", "source_url": "https://www.etsy.com/listing/4339516931/handmade-sea-snail-shell-necklace-long", "category": "Seashell Jewelry", "image_url": null, "destination_url": "https://www.etsy.com/listing/4339516931/handmade-sea-snail-shell-necklace-long", "title": "Handmade Sea Snail Shell Necklace: Long Beaded Boho Pendant", "body": "Handmade Sea Snail Shell Necklace: Long Beaded Boho Pendant Style: coastal, boho, shell. Materials: shell, seed_beads. View details and available options on Etsy.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": null, "new_title": "Sea Snail Shell Necklace with Silver Seed Beads", "new_body": "A natural sea snail shell pendant suspended from delicate silver-colored seed beads. A long necklace for layered boho styling. From PearlsTreasuresArt. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/46725934/r/il/3d1a77/7090123133/il_1588xN.7090123133_e29l.jpg", "checked_at": "2026-10-13T03:24:46.019Z"}, {"queue_id": "aa7f0fae-ea20-4920-82c9-ea5f3309cc04", "shop": "PearlsTreasuresArt", "listing_id": "4348858512", "source_url": "https://www.etsy.com/listing/4348858512/pearl-tassel-seashell-earrings-handmade", "category": "Seashell Jewelry", "image_url": null, "destination_url": "https://www.etsy.com/listing/4348858512/pearl-tassel-seashell-earrings-handmade", "title": "Pearl Tassel Seashell Earrings: Handmade Ocean-Inspired Statement Jewelry", "body": "Pearl Tassel Seashell Earrings: Handmade Ocean-Inspired Statement Jewelry Style: coastal, statement, shell. Materials: shell, pearl. View details and available options on Etsy.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": null, "new_title": "Seashell Earrings with Pearl Tassels", "new_body": "Sculpted natural shells and cascading pearl tassels create an ocean-inspired statement. Explore the asymmetrical design in the listing. From PearlsTreasuresArt. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/46725934/r/il/bbb469/7093657750/il_1588xN.7093657750_43bm.jpg", "checked_at": "2026-10-13T03:24:56.530Z"}, {"queue_id": "1e9c93be-2efd-468f-be09-55787ae47937", "shop": "QuGifts", "listing_id": "4315230146", "source_url": "https://www.etsy.com/listing/4315230146/seashell-wine-bottle-stopper-coastal-bar", "category": "Coastal Home Decor", "image_url": null, "destination_url": "https://www.etsy.com/listing/4315230146/seashell-wine-bottle-stopper-coastal-bar", "title": "Seashell Wine Bottle Stopper: Coastal Bar Accessory, Beach Wedding Favor", "body": "Seashell Wine Bottle Stopper: Coastal Bar Accessory, Beach Wedding Favor Style: coastal, beach, gift. Materials: shell, metal. View details and available options on Etsy.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "675399344056772225", "new_title": "Seashell Wine Bottle Stoppers for Coastal Decor", "new_body": "Natural seashells top metal bottle stoppers for a coastal bar cart or dining display. Choose your preferred shell style in the listing. From QuGifts. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/38006525/r/il/7862f2/6912698284/il_1588xN.6912698284_jvvn.jpg", "checked_at": "2026-10-13T03:25:05.421Z"}, {"queue_id": "185c4958-4ecd-4bb7-9565-10af1a668d2a", "shop": "QuGifts", "listing_id": "4348907433", "source_url": "https://www.etsy.com/listing/4348907433/handmade-cowrie-shell-tassel-coastal", "category": "Coastal Home Decor", "image_url": null, "destination_url": "https://www.etsy.com/listing/4348907433/handmade-cowrie-shell-tassel-coastal", "title": "Handmade Cowrie Shell Tassel: Coastal Boho Wall Hanging", "body": "Handmade Cowrie Shell Tassel: Coastal Boho Wall Hanging Style: coastal, boho, wabi_sabi. Materials: shell, cotton, polyester. View details and available options on Etsy.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "675399344056772225", "new_title": "Cowrie Shell Tassel for Coastal Wall Decor", "new_body": "White cowrie shells and soft tassels add texture to walls, doors or shelves. Explore the available lengths and designs. From QuGifts. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/38006525/r/il/e0a462/7141663931/il_1588xN.7141663931_9s9h.jpg", "checked_at": "2026-10-13T03:25:14.116Z"}, {"queue_id": "3826b92d-1c4f-4736-a29b-918b01e32bbd", "shop": "QuGifts", "listing_id": "4359523943", "source_url": "https://www.etsy.com/listing/4359523943/handmade-woven-seagrass-shell-basket", "category": "Coastal Home Decor", "image_url": null, "destination_url": "https://www.etsy.com/listing/4359523943/handmade-woven-seagrass-shell-basket", "title": "Handmade Woven Seagrass Shell Basket with Lid: Boho Desktop Organizer", "body": "Handmade Woven Seagrass Shell Basket with Lid: Boho Desktop Organizer Style: coastal, boho, rustic. Materials: seagrass, shell. View details and available options on Etsy.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "675399344056772225", "new_title": "Seagrass and Shell Basket with Lid", "new_body": "Woven seagrass and decorative shells make a small lidded basket for jewelry, keys or desk accessories. Explore the short and tall options. From QuGifts. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/38006525/r/il/4eb9c8/7216713737/il_1588xN.7216713737_qilf.jpg", "checked_at": "2026-10-13T03:25:26.152Z"}, {"queue_id": "e69191aa-b834-4edb-aafa-f9953bacf71c", "shop": "QuGifts", "listing_id": "4399003122", "source_url": "https://www.etsy.com/listing/4399003122/wood-bead-door-curtain-handmade-door", "category": "Coastal Home Decor", "image_url": null, "destination_url": "https://www.etsy.com/listing/4399003122/wood-bead-door-curtain-handmade-door", "title": "Wood Bead Door Curtain, Handmade Door Hanging, Boho Room Divider, Rustic Entryway Decor", "body": "Wood Bead Door Curtain, Handmade Door Hanging, Boho Room Divider, Rustic Entryway Decor Style: boho, rustic, minimal. Materials: wood, cotton. View details and available options on Etsy.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "675399344056772225", "new_title": "Wood Bead Door Curtain for Boho Interiors", "new_body": "Wooden beads on cotton cords bring natural texture to a doorway or room divider. Explore the available styles and measurements. From QuGifts. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/38006525/r/il/8e71d5/7407032277/il_1588xN.7407032277_3c21.jpg", "checked_at": "2026-10-13T03:25:35.705Z"}]'::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,new_title text,new_body text,checked_at timestamptz,new_image_url text);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '24 hours' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status in ('draft','ready') and cv.status in ('draft','ready') and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url is not distinct from x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id and h.platform='pinterest')
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 8 then raise exception 'Expected 8 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update products p set listing_status='active',last_seen_at=x.checked_at from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set status=case when x.board_id is null then 'draft'::content_status else 'ready'::content_status end,title=x.new_title,body=x.new_body,image_url=x.new_image_url from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select x.queue_id,x.board_id,pinterest_publish_snapshot(x.queue_id),x.checked_at,x.source_url from reviewed_input x where x.board_id is not null on conflict(queue_id) do nothing;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft' and x.board_id is not null;
select json_build_object('queue_id',q.id,'status',q.status,'board_id',rev.board_id,'snapshot_matches',rev.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',rev.listing_checked_at) from publish_queue q join reviewed_input x on x.queue_id=q.id left join pinterest_publish_reviews rev on rev.queue_id=q.id;
select json_build_object('public_publish_enabled',enabled) from pinterest_publish_settings where singleton;
commit;
